package com.pulselens.analytics.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="notifications") public class UserNotification {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private Long userId;@Column(nullable=false) private String title;@Column(nullable=false,length=1000) private String message;private boolean readFlag=false;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public boolean isReadFlag(){return readFlag;}public void setReadFlag(boolean v){readFlag=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
